// ============================================================
// MODO PRUEBA
// Cambia MODO_PRUEBA a true para probar sin importar la fecha
// Cambia TELEFONO_PRUEBA a TU numero para recibir los mensajes
// ============================================================
const MODO_PRUEBA = false;
const TELEFONO_PRUEBA = '+502XXXXXXXX'; // <-- pon tu numero aqui
// ============================================================

const hoy = new Date();
const pad = n => n.toString().padStart(2, '0');
const hoyStr = pad(hoy.getDate()) + '/' + pad(hoy.getMonth() + 1) + '/' + hoy.getFullYear();

const resultado = [];

for (const item of $input.all()) {
  const fila = item.json;
  const estado = (fila['Estado'] || '').trim();
  const seg1   = (fila['Fecha Seg1'] || '').toString().trim();
  const seg2   = (fila['Fecha Seg2'] || '').toString().trim();
  let   tel    = (fila['Telefono'] || '').toString().trim();

  const esHoy     = MODO_PRUEBA ? (seg1 !== '' || seg2 !== '') : (seg1 === hoyStr || seg2 === hoyStr);
  const pendiente = estado === 'Pendiente' || estado === '';

  if (esHoy && pendiente && tel) {
    // En modo prueba, redirigir todos los mensajes al numero de prueba
    if (MODO_PRUEBA) tel = TELEFONO_PRUEBA;

    resultado.push({
      json: {
        ...fila,
        Telefono: tel,
        _hoy: hoyStr,
        _esSeg2: MODO_PRUEBA ? false : (seg2 === hoyStr)
      }
    });
  }
}

console.log('MODO_PRUEBA:', MODO_PRUEBA);
console.log('Filas para enviar hoy:', resultado.length);
return resultado;

// Mensaje para seguimiento POST-EMPLEO
const resultados = [];

for (const item of $input.all()) {
  const d       = item.json;
  const esSeg2  = d._esSeg2;
  const nombre  = d['Nombre'] || 'amigo/a';
  const empresa = d['Empresa'] || 'tu nuevo trabajo';

  let mensaje;
  if (!esSeg2) {
    mensaje =
      'Hola ' + nombre + '! Esperamos que vayas bien en ' + empresa + '. ' +
      'Queremos saber como te va.\n\n' +
      '1. Como va tu adaptacion?\n   A) Excelente  B) Bien  C) Regular  D) Dificil\n\n' +
      '2. Te sientes apoyado por tu equipo?\n   A) Si  B) Parcialmente  C) No\n\n' +
      '3. En que podemos ayudarte? (escribe libremente)\n\n' +
      'Equipito Empleabilidad';
  } else {
    mensaje =
      'Hola ' + nombre + '! Han pasado 2 semanas en ' + empresa + '. ' +
      'Queremos saber como sigues.\n\n' +
      '1. Que es lo mejor de tu trabajo hasta ahora? (escribe libremente)\n\n' +
      '2. Te sientes mas comodo que la primera semana?\n   A) Mucho mas  B) Igual  C) Aun dificil\n\n' +
      '3. Hay algo en lo que podamos apoyarte? (escribe libremente)\n\n' +
      'Equipito Empleabilidad';
  }

  resultados.push({
    json: { ...d, _mensaje: mensaje, _tipoMensaje: esSeg2 ? 'Seg2' : 'Seg1' }
  });
}

return resultados;

// Mensaje para seguimiento BUSQUEDA ACTIVA
const resultados = [];

for (const item of $input.all()) {
  const d      = item.json;
  const esSeg2 = d._esSeg2;
  const nombre = d['Nombre'] || 'amigo/a';

  let mensaje;
  if (!esSeg2) {
    mensaje =
      'Hola ' + nombre + '! Somos del Equipito Empleabilidad. ' +
      'Sabemos que estas buscando trabajo y queremos apoyarte.\n\n' +
      '1. Cuantas empresas has contactado esta semana? (escribe el numero)\n\n' +
      '2. Has tenido alguna entrevista?\n   A) Si  B) No\n\n' +
      '3. En que podemos ayudarte mas?\n   A) CV  B) Preparacion entrevista  C) Buscar vacantes  D) Otro\n\n' +
      'Equipito Empleabilidad';
  } else {
    mensaje =
      'Hola ' + nombre + '! Como va tu busqueda de trabajo esta semana?\n\n' +
      '1. Has recibido alguna oferta?\n   A) Si  B) Pendiente  C) No todavia\n\n' +
      '2. Que tipo de trabajo buscas ahora? (escribe libremente)\n\n' +
      '3. Como te sientes con el proceso?\n   A) Optimista  B) Neutral  C) Necesito apoyo\n\n' +
      'Equipito Empleabilidad';
  }

  resultados.push({
    json: { ...d, _mensaje: mensaje, _tipoMensaje: esSeg2 ? 'Seg2' : 'Seg1' }
  });
}

return resultados;
